use super::*;
use crate::obligations::ObligationKind;
use crate::spending::categorise;

/// Whether an obligation is essential, and whether the table could place it at all.
///
/// An obligation nothing can place is treated as ESSENTIAL — for a floor, over-stating is the safe
/// direction and under-stating is a missed payment. It is NAMED rather than quietly promoted.
pub(crate) fn obligation_is_essential(label: &str, kind: ObligationKind) -> (bool, bool) {
    // A missed minimum is a credit event, not a cancelled luxury. Essential regardless of wording.
    if kind == ObligationKind::Minimum {
        return (true, true);
    }
    match categorise(label) {
        None => (true, false),
        Some(c) => (is_essential_category(c), true),
    }
}
